import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: EduMática (Trimestre Único)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Edumatica/Planificacion_Trimestre_IV-XII.md","filePath":"materias/Edumatica/Planificacion_Trimestre_IV-XII.md"}'),r={name:"materias/Edumatica/Planificacion_Trimestre_IV-XII.md"};function t(c,a,d,s,l,u){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="planificacion-academica-edumatica-trimestre-unico" tabindex="-1">Planificación Académica: EduMática (Trimestre Único) <a class="header-anchor" href="#planificacion-academica-edumatica-trimestre-unico" aria-label="Permalink to &quot;Planificación Académica: EduMática (Trimestre Único)&quot;">​</a></h1><p>Este trimestre cubre la totalidad del contenido programático (Unidades 1 a la 5), enfocándose en teorías del aprendizaje, diseño instruccional y la elaboración de software educativo.</p><hr><h2 id="📅-trimestre-unico-edumatica-unidades-1-a-5" tabindex="-1">📅 Trimestre Único: EduMática (Unidades 1 a 5) <a class="header-anchor" href="#📅-trimestre-unico-edumatica-unidades-1-a-5" aria-label="Permalink to &quot;📅 Trimestre Único: EduMática (Unidades 1 a 5)&quot;">​</a></h2><p><strong>Periodo:</strong> 21/09/2026 al 28/11/2026</p><h3 id="📝-evaluacion-1-fundamentos-y-objetivos-de-aprendizaje-unidades-1-y-2" tabindex="-1">📝 Evaluación 1: Fundamentos y Objetivos de Aprendizaje (Unidades 1 y 2) <a class="header-anchor" href="#📝-evaluacion-1-fundamentos-y-objetivos-de-aprendizaje-unidades-1-y-2" aria-label="Permalink to &quot;📝 Evaluación 1: Fundamentos y Objetivos de Aprendizaje (Unidades 1 y 2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Comprender las bases teóricas de la instrucción y redactar objetivos correctamente.</p><ul><li>Teorías de la instrucción y el aprendizaje (conductivismo, cognitivismo, constructivismo).</li><li>Identificación y redacción de objetivos de aprendizaje.</li><li>Modelos de Gagné-Briggs y la taxonomía de Bloom.</li><li><strong>Actividad:</strong> <strong>Exposición.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-ejecucion-de-microclase-unidad-3" tabindex="-1">📝 Evaluación 2: Ejecución de Microclase (Unidad 3) <a class="header-anchor" href="#📝-evaluacion-2-ejecucion-de-microclase-unidad-3" aria-label="Permalink to &quot;📝 Evaluación 2: Ejecución de Microclase (Unidad 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar y ejecutar una actividad didáctica integrando los elementos de la instrucción.</p><ul><li>Descripción y elementos de una microclase.</li><li>Ejecución de las técnicas correspondientes.</li><li><strong>Actividad:</strong> <strong>Exposición individual o en grupo de una microclase.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-diseno-curricular-y-sinoptico-unidad-4" tabindex="-1">📝 Evaluación 3: Diseño Curricular y Sinóptico (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-3-diseno-curricular-y-sinoptico-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 3: Diseño Curricular y Sinóptico (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Analizar y estructurar adecuadamente el contenido de una unidad curricular.</p><ul><li>Estructura de una unidad curricular y de un módulo.</li><li>Selección de contenidos, estrategias, recursos y evaluación.</li><li><strong>Actividad:</strong> <strong>Exposición.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-software-educativo-unidad-5" tabindex="-1">📝 Evaluación 4: Software Educativo (Unidad 5) <a class="header-anchor" href="#📝-evaluacion-4-software-educativo-unidad-5" aria-label="Permalink to &quot;📝 Evaluación 4: Software Educativo (Unidad 5)&quot;">​</a></h3><p><strong>Objetivo:</strong> Producir un prototipo funcional de software orientado a la educación.</p><ul><li>Modelos de elaboración y tipos de software educativo.</li><li>Diseño de <em>storyboard</em> aplicando eventos de Gagné.</li><li>Creación de un prototipo interactivo o funcional.</li><li><strong>Actividad:</strong> <strong>Entrega de Proyecto (Prototipo de Software).</strong> (25%)</li></ul><blockquote><p><strong>Nota Adicional:</strong> El instrumento de <strong>coevaluación y auto-evaluación</strong> exigido por el temario se aplicará transversalmente durante las actividades prácticas (Exposiciones de la Microclase y del Software Educativo).</p></blockquote><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el trimestre, el alumno no solo comprenderá las teorías clásicas y contemporáneas de la educación, sino que será capaz de diseñar un programa de asignatura, dictar una microclase y construir el prototipo de un software educativo como proyecto integrador.</p>',21)])])}const v=e(r,[["render",t]]);export{p as __pageData,v as default};
